import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.Dhf_H6O0.js";const n="/mbit-mcpo-proxy-download/guide/images/servers-list.png",i="/mbit-mcpo-proxy-download/guide/images/add-server-stdio.png",v=JSON.parse('{"title":"Managing Servers","description":"","frontmatter":{},"headers":[],"relativePath":"using-the-app/manage-servers.md","filePath":"using-the-app/manage-servers.md"}'),s={name:"using-the-app/manage-servers.md"};function d(l,e,h,g,p,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="managing-servers" tabindex="-1">Managing Servers <a class="header-anchor" href="#managing-servers" aria-label="Permalink to &quot;Managing Servers&quot;">​</a></h1><p>Servers are MCP server definitions that tell the gateway how to connect to each tool provider. You can add them manually, from the <a href="./../catalog/browsing.html">Catalog</a>, or by <a href="./import-servers.html">importing JSON</a>.</p><h2 id="the-servers-page" tabindex="-1">The Servers page <a class="header-anchor" href="#the-servers-page" aria-label="Permalink to &quot;The Servers page&quot;">​</a></h2><p>Click <strong>Servers</strong> in the sidebar to see all your server definitions.</p><p><img src="'+n+'" alt="Servers page"></p><p>Each row shows:</p><ul><li><strong>Name</strong> — a unique identifier for this server</li><li><strong>Transport</strong> — the connection type (Streamable HTTP, SSE, or stdio)</li><li><strong>Disable / Enable</strong> — toggle whether this server is included in the gateway config</li><li><strong>Edit</strong> — open the server definition for editing</li><li><strong>Delete</strong> — remove the server definition</li></ul><h2 id="adding-a-server" tabindex="-1">Adding a server <a class="header-anchor" href="#adding-a-server" aria-label="Permalink to &quot;Adding a server&quot;">​</a></h2><ol><li>Click <strong>+ Add server</strong> in the top-right.</li><li>The Add Server dialog opens:</li></ol><p><img src="'+i+'" alt="Add Server dialog — stdio transport"></p><ol start="3"><li>Fill in the fields (see below for each transport type).</li><li>Check <strong>Enabled</strong> if you want this server active immediately.</li><li>Click <strong>Save</strong>.</li><li>Go to Home and click <strong>Apply &amp; Restart</strong> to make the gateway pick up the new server.</li></ol><h3 id="fields-by-transport-type" tabindex="-1">Fields by transport type <a class="header-anchor" href="#fields-by-transport-type" aria-label="Permalink to &quot;Fields by transport type&quot;">​</a></h3><p><strong>stdio</strong> (runs a local program):</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td>Name</td><td>Unique server name</td><td><code>memory</code></td></tr><tr><td>Command</td><td>The program to run</td><td><code>npx</code></td></tr><tr><td>Arguments</td><td>One per line</td><td><code>-y</code> and <code>@modelcontextprotocol/server-memory</code></td></tr><tr><td>Environment Variables</td><td><code>KEY=VALUE</code> per line</td><td><code>API_KEY=secret</code></td></tr></tbody></table><p><strong>SSE</strong> (remote server, Server-Sent Events):</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td>Name</td><td>Unique server name</td><td><code>my-sse-server</code></td></tr><tr><td>URL</td><td>The server endpoint</td><td><code>https://example.com/mcp/sse</code></td></tr><tr><td>Headers</td><td>Optional HTTP headers</td><td><code>Authorization: Bearer token123</code></td></tr></tbody></table><p><strong>streamable-http</strong> (remote server, HTTP streaming):</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td>Name</td><td>Unique server name</td><td><code>telecontext</code></td></tr><tr><td>URL</td><td>The server endpoint</td><td><code>https://telecontext.trap.ng.telekom.net/mcp</code></td></tr><tr><td>Headers</td><td>Optional HTTP headers</td><td>—</td></tr><tr><td>OAuth</td><td>Client ID, scopes, auth/token URLs</td><td>Filled automatically for Telecontext</td></tr></tbody></table><p>See <a href="./server-types.html">Server Types Explained</a> for when to use which transport.</p><h2 id="editing-a-server" tabindex="-1">Editing a server <a class="header-anchor" href="#editing-a-server" aria-label="Permalink to &quot;Editing a server&quot;">​</a></h2><ol><li>Click <strong>Edit</strong> on the server row.</li><li>Modify any field.</li><li>Click <strong>Save</strong>.</li><li>Go to Home → <strong>Apply &amp; Restart</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Telecontext servers</p><p>When you edit a Telecontext server, the full category/tool configurator opens so you can change which tools are active without leaving the edit dialog.</p></div><h2 id="enabling-and-disabling" tabindex="-1">Enabling and disabling <a class="header-anchor" href="#enabling-and-disabling" aria-label="Permalink to &quot;Enabling and disabling&quot;">​</a></h2><p>Click <strong>Disable</strong> to exclude a server from the gateway config without deleting it. The server definition is preserved — you can re-enable it anytime.</p><p>Disabled servers are <strong>not</strong> included in the generated <code>config.json</code> and won&#39;t appear in the gateway.</p><p>After toggling, click <strong>Apply &amp; Restart</strong> on Home.</p><h2 id="deleting-a-server" tabindex="-1">Deleting a server <a class="header-anchor" href="#deleting-a-server" aria-label="Permalink to &quot;Deleting a server&quot;">​</a></h2><p>Click <strong>Delete</strong> on the server row. This permanently removes the definition. If you want to keep it for later, use <strong>Disable</strong> instead.</p>',28)])])}const b=t(s,[["render",d]]);export{v as __pageData,b as default};
